import{_ as s,a0 as i,w as r,s as d,ao as p,I as t,x as e,a1 as n,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"安卓編年史（20）：安卓 4.1，果凍豆——Google Now 指明未來 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史（20）：安卓 4.1，果凍豆——Google Now 指明未來 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史（20）：安卓 4.1，果凍豆——Google Now 指明未來 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史（20）：安卓 4.1，果凍豆——Google Now 指明未來 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/21 - The history of Android","title":"安卓編年史（20）：安卓 4.1，果凍豆——Google Now 指明未來","tag":"The history of Android","desc":""},"relativePath":"The history of Android/21 - The history of Android.md","filePath":"[post].md"}'),g={name:"The history of Android/21 - The history of Android.md"};function m(u,o,f,T,h,w){const l=i("Link");return r(),d("div",null,[o[20]||(o[20]=p('<h1 id="安卓編年史-20-安卓-4-1-果凍豆——google-now-指明未來" tabindex="-1">安卓編年史（20）：安卓 4.1，果凍豆——Google Now 指明未來 <a class="header-anchor" href="#安卓編年史-20-安卓-4-1-果凍豆——google-now-指明未來" aria-label="Permalink to “安卓編年史（20）：安卓 4.1，果凍豆——Google Now 指明未來”">​</a></h1><h3 id="安卓-4-1-果凍豆——google-now指明未來" tabindex="-1">安卓 4.1，果凍豆——Google Now指明未來 <a class="header-anchor" href="#安卓-4-1-果凍豆——google-now指明未來" aria-label="Permalink to “安卓 4.1，果凍豆——Google Now指明未來”">​</a></h3><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/ASUS_Google_Nexus_7_4_11.jpg" alt="華碩製造的 Nexus 7，安卓 4.1 的首發設備"></p><p><em>華碩製造的 Nexus 7，安卓 4.1 的首發設備</em></p><p>隨着 2012 年 7 月安卓 4.1 果凍豆的發佈，谷歌的安卓發佈節奏進入每六個月一發布的軌道。平台已經成熟，三個月的發佈週期就沒那麼必要了，更長的發佈週期也給了 OEM 廠商足夠的時間跟上谷歌的節奏。和蜂巢不同，小數點後的更新發布現在是主要更新，4.1 帶來了主要的界面更新和框架變化。</p><p>果凍豆最大的變化之一，並且你在截圖中看不到的是“黃油計劃”，這個名字代表了谷歌工程師讓安卓的動畫順暢地跑在 30FPS 上的努力。還有一些核心變化，像垂直同步和三重緩衝，每個動畫都經過優化以流暢地繪製。動畫和順滑滾動一直是安卓和 iOS 相比之下的弱點。經過在核心動畫框架和單獨的應用上的努力，果凍豆讓安卓的流暢度大幅接近 iOS。</p>',6)),t("p",null,[o[1]||(o[1]=e("和果凍豆一起到來的還有 ",-1)),n(l,{href:"http://arstechnica.com/gadgets/2012/07/divine-intervention-googles-nexus-7-is-a-fantastic-200-tablet/"},{default:a(()=>[...o[0]||(o[0]=[e("Nexus",-1)])]),_:1}),o[2]||(o[2]=e(" 7，由華碩生產的 7 英寸平板。不像之前主要是橫屏模式的 Xoom，Nexus 7 主要以豎屏模式使用，像個大一號的手機。Nexus 7 展現了經過一年半的生態建設，谷歌已經準備好了給平板市場帶來一部旗艦設備。和 Nexus One 和 GSM Galaxy Nexus 一樣，Nexus 7 直接由谷歌在線銷售。儘管那些早先的設備對習慣於運營商補貼的消費者來説價格高的驚人，Nexus 7 以僅僅 200 美元的價格推向大眾市場。這個價格給你帶來一部 7 英寸、1280x800 英寸顯示屏、四核 1.2GHz Tegra 3 處理器、1GB 內存、8GB 內置存儲的設備。Nexus 7 的性價比如此之高，許多人都想知道谷歌到底有沒有在其旗艦平板上賺到錢。",-1))]),o[21]||(o[21]=p('<p>更小、更輕、7 英寸，這些因素促成了谷歌巨大的成功，並且將谷歌帶向了引領行業潮流的位置。一開始製造 10 英寸 iPad 的蘋果，最終也不得不推出和 Nexus 7 相似的 iPad Mini 來應對。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/picture.png" alt="4.1 的新鎖屏設計，壁紙，以及系統按鈕新的點擊高亮。"></p><p><em>4.1 的新鎖屏設計，壁紙，以及系統按鈕新的點擊高亮。 [Ron Amadeo 供圖]</em></p><p>蜂巢引入的電子風格在冰淇淋三明治中有所減少，果凍豆在此之上走得更遠。它開始從系統中大範圍地移除藍色。跡象就是系統按鈕的點擊高亮從藍色變為了灰色。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/jb-apps-and-notications.png" alt="新應用陣容合成圖以及新的消息可展開通知面板。"></p><p><em>新應用陣容合成圖以及新的消息可展開通知面板。 [Ron Amadeo 供圖]</em></p><p>通知中心面板完全重製了，這個設計一直沿用到今天的奇巧巧克力（KitKat）。新面板擴展到了屏幕頂部，並且覆蓋了狀態欄圖標，這意味着通知面板打開的時候不再能看到狀態欄。時間突出顯示在左上角，旁邊是日期和設置按鈕。清除所有通知的按鈕，在冰淇淋三明治中顯示為一個“X”按鈕，現在變為階梯狀的按鈕，象徵着清除所有通知的時候消息交錯滑動的動畫效果。底部的面板把手從一個小圓換成了一條直線，和麪板等寬。所有的排版都發生了變化——通知面板的所有項現在都使用了更大，更細的字體。通知面板是另一個從冰淇淋三明治和蜂巢中引入的藍色元素被移除的屏幕。除了觸摸高亮之外整個通知面板都是灰色的。</p><p>通知面板也引入了新功能。相較於之前的兩行設計，現在的通知消息可以展開以顯示更多信息。通知消息可以顯示最多 8 行文本，甚至還能在消息底部顯示按鈕。屏幕截圖通知消息底部有個分享按鈕，你也可以直接從未接來電通知中撥號，或者將一個正在響鈴的鬧鐘小睡，這些都可以在通知面板完成。新通知消息默認展開，但當它們堆疊到一起時會恢復原來的尺寸。在通知消息上雙指向下滑動可以展開消息。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/googlenow.png" alt="新谷歌搜索應用，帶有 Google Now 卡片，語音搜索，以及文字搜索。"></p><p><em>新谷歌搜索應用，帶有 Google Now 卡片，語音搜索，以及文字搜索。 [Ron Amadeo 供圖]</em></p><p>果凍豆中不止對安卓而言，也是對谷歌來説最大的特性，是新版谷歌搜索應用。它帶來了“Google Now”，一個預測性搜索功能。Google Now 在搜索框下面顯示為幾張卡片，它會提供谷歌認為你所關心的事物的搜索結果。就比如谷歌地圖搜索你最近在桌面電腦查找的地點或日曆的約會地點、天氣，以及旅行時回家的時間。</p><p>新版谷歌搜索應用自然可以從谷歌圖標啓動，但它還可以在任意屏幕從系統欄上滑訪問。長按系統欄會喚出一個類似鎖屏解鎖的環。卡片部分縱向滾動，如果你不想看到它們，可以滑動消除它們。語音搜索是更新的一個大部分。提問不是無腦地輸入進谷歌，如果谷歌知道答案，它還會用文本語音轉換引擎回答你。傳統的文字搜索當然也支持。只需點擊搜索欄然後開始輸入即可。</p><p>谷歌經常將 Google Now 稱作“谷歌搜索的未來”。告訴谷歌你想要什麼這還不夠好。谷歌想要在你之前知道你想要什麼。Google Now 用谷歌所有的數據挖掘關於你的知識為你服務，這也是谷歌對抗搜索引擎競爭對手，比如必應，的最大優勢所在。智能手機比你擁有的其它設備更瞭解你，所以該服務在安卓上首次亮相。但谷歌慢慢也將 Google Now 加入 Chrome，最終似乎會到達 Google.com。</p><p>儘管功能很重要，但同時 Google Now 是谷歌產品有史以來最重要的設計工作也是毋庸置疑的。谷歌搜索應用引入的白色卡片審美將會成為幾乎所有谷歌產品設計的基礎。今天，卡片風格被用在 Google Play 商店以及所有的 Play 內容應用，Youtube、谷歌地圖、Drive、Keep、Gmail、Google+ 以及其它產品。同時也不限於安卓應用。不少谷歌的桌面站點和 iOS 應用也以此設計為靈感。設計是谷歌歷史上的弱項之一，但 Google Now 開始谷歌最終在設計上採取了行動，帶來一個統一的，全公司範圍的設計語言。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/yotuube.png" alt="又一個 Youtube 重新設計，信息密度有所下降。"></p><p><em>又一個 Youtube 的重新設計，信息密度有所下降。 [Ron Amadeo 供圖]</em></p><p>又一個版本，又一個 Youtube 的重新設計。這次列表視圖主要基於略縮圖，大大的圖片佔據了屏幕的大部分。信息密度在新列表設計中有所下降。之前 Youtube 每屏大約能顯示 6 個項目，現在只能顯示 3 個。</p><p>Youtube 是首批在應用左側加入滑動抽屜的應用之一，該特性會成為谷歌應用的標準設計風格。抽屜中有你的賬户的鏈接和訂閲頻道，這讓谷歌可以去除頁面頂部標籤頁設計。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2013/08/playservicesdiagram2.png" alt="Google Play 服務的職責以及安卓的剩餘部分職責。"></p><p><em>Google Play 服務的職責以及安卓的剩餘部分職責。 [Ron Amadeo 供圖]</em></p><h3 id="google-play-服務——碎片化和讓系統版本-幾乎-過時" tabindex="-1">Google Play 服務——碎片化和讓系統版本（幾乎）過時 <a class="header-anchor" href="#google-play-服務——碎片化和讓系統版本-幾乎-過時" aria-label="Permalink to “Google Play 服務——碎片化和讓系統版本（幾乎）過時”">​</a></h3><p>碎片化那時候看起來這並不是個大問題，但 2012 年 12 月，Google Play 服務 1.0 面向所有安卓 2.2 及以上版本的手機推出。它添加了一些 Google+ API 和對 OAuth 2.0 的支持。</p><p>儘管這個升級聽起來很無聊，但 Google Play 服務最終會成長為安卓整體的一部分。Google Play 服務扮演着正常應用和安卓系統的中間角色，使得谷歌可以升級或替換一些核心組件，並在不發佈新安卓版本的前提下添加 API。</p><p>有了 Play 服務，谷歌有了直接接觸安卓手機核心部分的能力，而不用通過 OEM 更新一集運營商批准的過程。谷歌使用 Play 服務添加了全新的位置系統、惡意軟件掃描、遠程擦除功能，以及新的谷歌地圖 API，所有的這一切都不用通過發佈一個系統更新實現。正如我們在薑餅部分的結尾提到的，感謝 Play 服務裏這些“可移植的”API 實現，薑餅仍然能夠下載現代版本的 Play 商店和許多其他的谷歌應用。</p>',24)),t("p",null,[o[4]||(o[4]=e("另一個巨大的益處是安卓用户基礎的兼容性。最新版本的安卓系統要經過很長時間到達大多數用户手中，這意味着最新版本系統綁定的 API 在大多數用户升級之前對開發者來説沒有任何意義。Google Play 服務兼容凍酸奶及以上版本，換句話説就是 99% 的活躍設備，並且更新可以直接通過 Play 商店直接推送到手機上。通過將 API 包含在 Google Play 服務中而不是安卓中，谷歌可以在一週內將新 API 推送到幾乎所有用户手中。這對許多版本碎片化引起的問題來説是個",-1)),n(l,{href:"http://arstechnica.com/gadgets/2013/09/balky-carriers-and-slow-oems-step-aside-google-is-defragging-android/"},{default:a(()=>[...o[3]||(o[3]=[e("偉大的解決方案",-1)])]),_:1}),o[5]||(o[5]=e("。",-1))]),o[22]||(o[22]=t("hr",null,null,-1)),o[23]||(o[23]=t("p",null,[t("img",{src:"https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg",alt:"Ron Amadeo"})],-1)),t("p",null,[n(l,{href:"http://arstechnica.com/author/ronamadeo"},{default:a(()=>[...o[6]||(o[6]=[e("Ron Amadeo",-1)])]),_:1}),o[8]||(o[8]=e(" / Ron 是 Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1)),n(l,{href:"https://twitter.com/RonAmadeo"},{default:a(()=>[...o[7]||(o[7]=[e("@RonAmadeo",-1)])]),_:1})]),o[24]||(o[24]=t("hr",null,null,-1)),t("p",null,[o[10]||(o[10]=e("via: ",-1)),n(l,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/21/"},{default:a(()=>[...o[9]||(o[9]=[e("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/21/",-1)])]),_:1})]),t("p",null,[o[13]||(o[13]=e("譯者：",-1)),n(l,{href:"https://github.com/alim0x"},{default:a(()=>[...o[11]||(o[11]=[e("alim0x",-1)])]),_:1}),o[14]||(o[14]=e(" 校對：",-1)),n(l,{href:"https://github.com/wxy"},{default:a(()=>[...o[12]||(o[12]=[e("wxy",-1)])]),_:1})]),t("p",null,[o[17]||(o[17]=e("本文由 ",-1)),n(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...o[15]||(o[15]=[e("LCTT",-1)])]),_:1}),o[18]||(o[18]=e(" 原創翻譯，",-1)),n(l,{href:"http://linux.cn/"},{default:a(()=>[...o[16]||(o[16]=[e("Linux中國",-1)])]),_:1}),o[19]||(o[19]=e(" 榮譽推出",-1))])])}const A=s(g,[["render",m]]);export{y as __pageData,A as default};
